package consumer

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/metorial/cli/internal/app"
	"github.com/metorial/cli/internal/commandutil"
	"github.com/metorial/cli/internal/config"
	"github.com/metorial/cli/internal/terminal"
	"github.com/spf13/cobra"
)

func newTestCommand(t *testing.T, apiHost string, name string) (*cobra.Command, *bytes.Buffer) {
	t.Helper()

	stdout := &bytes.Buffer{}
	features := terminal.Features{Width: 120}
	application := app.NewWithIO(bytes.NewReader(nil), stdout, &bytes.Buffer{}, features, features)
	application.SetSubjectType(config.SubjectTypeConsumer)

	ctx := commandutil.NewContext(application, &commandutil.RootOptions{
		APIKey:  "[REDACTED]",
		APIHost: apiHost,
		Format:  "json",
	})

	for _, command := range NewCommands(ctx) {
		if command.Name() == name {
			command.SetOut(stdout)
			command.SetErr(&bytes.Buffer{})
			return command, stdout
		}
	}

	t.Fatalf("command %q not found", name)
	return nil, nil
}

func TestSetupPollsUntilSuccessfulThenDeploys(t *testing.T) {
	t.Setenv("HOME", t.TempDir())

	previousInterval := setupPollInterval
	setupPollInterval = time.Millisecond
	t.Cleanup(func() { setupPollInterval = previousInterval })

	polls := 0
	calls := []string{}
	var deployBody map[string]any

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls = append(calls, r.Method+" "+r.URL.Path)
		w.Header().Set("Content-Type", "application/json")

		switch {
		case r.Method == http.MethodGet && r.URL.Path == "/consumer/providers/cat_1":
			_ = json.NewEncoder(w).Encode(map[string]any{
				"id":                "cat_1",
				"type":              "provider_template",
				"name":              "GitHub",
				"availability":      "available_now",
				"provider_template": map[string]any{"id": "ptpl_1", "name": "GitHub"},
				"auth_methods": []map[string]any{
					{"id": "pam_token", "type": "token", "name": "Token"},
					{"id": "pam_oauth", "type": "oauth", "name": "OAuth"},
				},
			})
		case r.Method == http.MethodPost && r.URL.Path == "/consumer/providers/cat_1/setup":
			body := map[string]any{}
			raw, _ := io.ReadAll(r.Body)
			_ = json.Unmarshal(raw, &body)
			if body["provider_auth_method_id"] != "pam_oauth" {
				t.Errorf("setup should prefer the OAuth auth method, got %v", body)
			}
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "iss_1", "status": "pending"})
		case r.Method == http.MethodGet && r.URL.Path == "/consumer/providers/cat_1/setup/iss_1":
			polls++
			status := "pending"
			if polls >= 2 {
				status = "successful"
			}
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "iss_1", "status": status})
		case r.Method == http.MethodPost && r.URL.Path == "/consumer/providers/cat_1/deploy":
			raw, _ := io.ReadAll(r.Body)
			_ = json.Unmarshal(raw, &deployBody)
			_ = json.NewEncoder(w).Encode(map[string]any{
				"id":        "mms_1",
				"status":    "active",
				"name":      "Work GitHub",
				"endpoints": []map[string]any{{"id": "mmse_1", "alias": "work-github", "url": "https://mcp.example/work-github"}},
			})
		default:
			w.WriteHeader(http.StatusNotFound)
			_ = json.NewEncoder(w).Encode(map[string]any{"message": "unexpected " + r.Method + " " + r.URL.Path})
		}
	}))
	defer server.Close()

	command, stdout := newTestCommand(t, server.URL, "setup")
	command.SetArgs([]string{"cat_1", "--name", "Work GitHub"})
	if err := command.Execute(); err != nil {
		t.Fatalf("Execute() error = %v (calls: %v)", err, calls)
	}

	if polls != 2 {
		t.Fatalf("polls = %d, want 2", polls)
	}
	if deployBody["integration_setup_session_id"] != "iss_1" || deployBody["name"] != "Work GitHub" {
		t.Fatalf("deploy body = %v", deployBody)
	}

	result := map[string]any{}
	if err := json.Unmarshal(stdout.Bytes(), &result); err != nil {
		t.Fatalf("output is not JSON: %v\n%s", err, stdout.String())
	}
	integration, _ := result["integration"].(map[string]any)
	if integration["id"] != "mms_1" {
		t.Fatalf("output integration = %v", result["integration"])
	}
}

func TestSetupStopsOnExpiredSession(t *testing.T) {
	t.Setenv("HOME", t.TempDir())

	previousInterval := setupPollInterval
	setupPollInterval = time.Millisecond
	t.Cleanup(func() { setupPollInterval = previousInterval })

	deployed := false
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		switch {
		case r.URL.Path == "/consumer/providers/cat_1":
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "cat_1", "type": "provider_template", "name": "GitHub", "availability": "available_now"})
		case strings.HasSuffix(r.URL.Path, "/setup"):
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "iss_1", "status": "pending"})
		case strings.HasSuffix(r.URL.Path, "/setup/iss_1"):
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "iss_1", "status": "expired"})
		case strings.HasSuffix(r.URL.Path, "/deploy"):
			deployed = true
			_ = json.NewEncoder(w).Encode(map[string]any{"id": "mms_1"})
		}
	}))
	defer server.Close()

	command, _ := newTestCommand(t, server.URL, "setup")
	command.SetArgs([]string{"cat_1"})
	err := command.Execute()
	if err == nil || !strings.Contains(err.Error(), "expired") {
		t.Fatalf("Execute() error = %v, want an expired session error", err)
	}
	if deployed {
		t.Fatalf("deploy should not be called for an expired setup session")
	}
}

func TestSetupRejectsRequestAccessItems(t *testing.T) {
	t.Setenv("HOME", t.TempDir())

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.URL.Path != "/consumer/providers/cat_1" {
			t.Errorf("unexpected request %s %s", r.Method, r.URL.Path)
		}
		_ = json.NewEncoder(w).Encode(map[string]any{"id": "cat_1", "type": "provider_template", "name": "Salesforce", "availability": "request_access"})
	}))
	defer server.Close()

	command, _ := newTestCommand(t, server.URL, "setup")
	command.SetArgs([]string{"cat_1"})
	err := command.Execute()
	if err == nil || !strings.Contains(err.Error(), "metorial request-access cat_1") {
		t.Fatalf("Execute() error = %v, want a request-access hint", err)
	}
}

package auth

import (
	"bytes"
	"strings"
	"testing"

	"github.com/metorial/cli/internal/config"
	"github.com/metorial/cli/internal/terminal"
)

func TestRenderLoginAuthScreenIncludesBrowserMessageWhenSupported(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer
	renderLoginAuthScreen(&output, terminal.Features{}, "https://app.metorial.com/cli/auth", "ABCD-1234", true)

	rendered := output.String()
	if !strings.Contains(rendered, "Please sign in to your Metorial account.") {
		t.Fatalf("renderLoginAuthScreen() missing sign-in copy: %q", rendered)
	}
	if !strings.Contains(rendered, "Verification Code: ABCD-1234") {
		t.Fatalf("renderLoginAuthScreen() missing verification code: %q", rendered)
	}
	if !strings.Contains(rendered, "Opening browser for Metorial authentication.") {
		t.Fatalf("renderLoginAuthScreen() missing browser copy: %q", rendered)
	}
}

func TestRenderLoginSuccess(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer
	renderLoginSuccess(&output, terminal.Features{})

	rendered := output.String()
	if !strings.Contains(rendered, "Logged in to Metorial successfully.") {
		t.Fatalf("renderLoginSuccess() missing success message: %q", rendered)
	}
	if !strings.Contains(rendered, "Get started by running `metorial`.") {
		t.Fatalf("renderLoginSuccess() missing next step: %q", rendered)
	}
}

func TestRenderLogoutSuccessWithoutRemainingProfiles(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer
	renderLogoutSuccess(&output, terminal.Features{}, config.Profile{
		Name:      "testing",
		OrgName:   "Testing Org",
		UserEmail: "test@example.com",
	}, nil)

	rendered := output.String()
	if !strings.Contains(rendered, "Logged out from Metorial successfully.") {
		t.Fatalf("renderLogoutSuccess() missing success message: %q", rendered)
	}
	if !strings.Contains(rendered, "Removed Profile: testing") {
		t.Fatalf("renderLogoutSuccess() missing removed profile: %q", rendered)
	}
	if !strings.Contains(rendered, "No profiles remain on this machine.") {
		t.Fatalf("renderLogoutSuccess() missing empty state: %q", rendered)
	}
	if !strings.Contains(rendered, "Run `metorial login` to add a new profile.") {
		t.Fatalf("renderLogoutSuccess() missing next step: %q", rendered)
	}
}

func TestRenderLogoutSuccessWithNextProfile(t *testing.T) {
	t.Parallel()

	var output bytes.Buffer
	renderLogoutSuccess(&output, terminal.Features{}, config.Profile{
		Name:      "testing",
		OrgName:   "Testing Org",
		UserEmail: "test@example.com",
	}, &config.Profile{
		Name: "backup",
	})

	rendered := output.String()
	if !strings.Contains(rendered, "Active profile: backup") {
		t.Fatalf("renderLogoutSuccess() missing next profile: %q", rendered)
	}
	if !strings.Contains(rendered, "Continue with the Metorial CLI using this profile.") {
		t.Fatalf("renderLogoutSuccess() missing continuation hint: %q", rendered)
	}
}

package agent

import "testing"

func TestIsAiAgent(t *testing.T) {
	tests := []struct {
		name      string
		envVar    string
		envValue  string
		wantOK    bool
		wantAgent string
	}{
		{name: "no env", wantOK: false, wantAgent: ""},
		{name: "antigravity", envVar: "ANTIGRAVITY_CLI_ALIAS", envValue: "1", wantOK: true, wantAgent: "antigravity"},
		{name: "claude code", envVar: "CLAUDECODE", envValue: "1", wantOK: true, wantAgent: "claude_code"},
		{name: "cline", envVar: "CLINE_ACTIVE", envValue: "1", wantOK: true, wantAgent: "cline"},
		{name: "codex sandbox", envVar: "CODEX_SANDBOX", envValue: "1", wantOK: true, wantAgent: "codex_cli"},
		{name: "codex thread", envVar: "CODEX_THREAD_ID", envValue: "1", wantOK: true, wantAgent: "codex_cli"},
		{name: "codex network disabled", envVar: "CODEX_SANDBOX_NETWORK_DISABLED", envValue: "1", wantOK: true, wantAgent: "codex_cli"},
		{name: "codex ci", envVar: "CODEX_CI", envValue: "1", wantOK: true, wantAgent: "codex_cli"},
		{name: "cursor", envVar: "CURSOR_AGENT", envValue: "1", wantOK: true, wantAgent: "cursor"},
		{name: "gemini", envVar: "GEMINI_CLI", envValue: "1", wantOK: true, wantAgent: "gemini_cli"},
		{name: "open code", envVar: "OPENCODE", envValue: "1", wantOK: true, wantAgent: "open_code"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for envVar := range envVarAgents {
				t.Setenv(envVar, "")
			}

			if tt.envVar != "" {
				t.Setenv(tt.envVar, tt.envValue)
			}

			gotOK, gotAgent := IsAiAgent()
			if gotOK != tt.wantOK {
				t.Fatalf("IsAiAgent() ok = %v, want %v", gotOK, tt.wantOK)
			}
			if gotAgent != tt.wantAgent {
				t.Fatalf("IsAiAgent() agent = %q, want %q", gotAgent, tt.wantAgent)
			}
		})
	}
}

package consumerapi

import (
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"strings"
	"testing"

	"github.com/metorial/cli/internal/config"
)

type recordedRequest struct {
	Method        string
	Path          string
	Query         url.Values
	Authorization string
	Headers       http.Header
	Body          map[string]any
}

func newTestClient(t *testing.T, handler func(w http.ResponseWriter, r *http.Request)) (*Client, *[]recordedRequest) {
	t.Helper()

	requests := []recordedRequest{}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		recorded := recordedRequest{
			Method:        r.Method,
			Path:          r.URL.Path,
			Query:         r.URL.Query(),
			Authorization: [REDACTED]"Authorization"),
			Headers:       r.Header.Clone(),
		}
		if raw, _ := io.ReadAll(r.Body); len(raw) > 0 {
			_ = json.Unmarshal(raw, &recorded.Body)
		}
		requests = append(requests, recorded)
		handler(w, r)
	}))
	t.Cleanup(server.Close)

	hostURL, err := url.Parse(server.URL)
	if err != nil {
		t.Fatalf("url.Parse() error = %v", err)
	}

	client, err := New(config.Runtime{APIKey: "[REDACTED]", APIHost: server.URL, APIHostURL: hostURL})
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}

	return client, &requests
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func TestListProvidersSendsFiltersWithoutImpersonationHeaders(t *testing.T) {
	client, requests := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]any{
			"items": []map[string]any{
				{"id": "cat_1", "type": "provider_template", "name": "GitHub", "availability": "available_now"},
			},
			"pagination": map[string]any{"has_more_after": true},
		})
	})

	result, err := client.ListProviders(ListOptions{Limit: 10, After: "cat_0"}, " git ", "grp_1")
	if err != nil {
		t.Fatalf("ListProviders() error = %v", err)
	}
	if len(result.Items) != 1 || result.Items[0].ID != "cat_1" || !result.Pagination.HasMoreAfter {
		t.Fatalf("ListProviders() = %+v", result)
	}

	request := (*requests)[0]
	if request.Method != http.MethodGet || request.Path != "/consumer/providers" {
		t.Fatalf("request = %s %s", request.Method, request.Path)
	}
	if request.Query.Get("search") != "git" || request.Query.Get("provider_group_id") != "grp_1" {
		t.Fatalf("query = %v", request.Query)
	}
	if request.Query.Get("limit") != "10" || request.Query.Get("after") != "cat_0" {
		t.Fatalf("pagination query = %v", request.Query)
	}
	if !strings.Contains(request.Authorization, "consumer-token") {
		t.Fatalf("Authorization = %q", request.Authorization)
	}
	for _, header := range []string{"Metorial-Instance-Id", "Metorial-Consumer-Profile-Id"} {
		if value := request.Headers.Get(header); value != "" {
			t.Fatalf("%s = %q, consumer tokens should not send it", header, value)
		}
	}
}

func TestSetupDeployAndReconnectBodies(t *testing.T) {
	client, requests := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		switch {
		case strings.HasSuffix(r.URL.Path, "/setup"):
			writeJSON(w, http.StatusOK, map[string]any{"id": "iss_1", "status": "pending", "url": "https://setup.example/iss_1"})
		default:
			writeJSON(w, http.StatusOK, map[string]any{"id": "mms_1", "status": "active"})
		}
	})

	session, err := client.StartSetup("cat_1", "pam_oauth")
	if err != nil {
		t.Fatalf("StartSetup() error = %v", err)
	}
	if session.ID != "iss_1" || session.URL != "https://setup.example/iss_1" {
		t.Fatalf("StartSetup() = %+v", session)
	}

	name := "My GitHub"
	if _, err := client.Deploy("cat_1", DeployInput{IntegrationSetupSessionID: "iss_1", Name: &name}); err != nil {
		t.Fatalf("Deploy() error = %v", err)
	}
	if _, err := client.Reconnect("cat_1", "mms_1", "iss_2"); err != nil {
		t.Fatalf("Reconnect() error = %v", err)
	}

	setup, deploy, reconnect := (*requests)[0], (*requests)[1], (*requests)[2]
	if setup.Method != http.MethodPost || setup.Path != "/consumer/providers/cat_1/setup" || setup.Body["provider_auth_method_id"] != "pam_oauth" {
		t.Fatalf("setup request = %+v", setup)
	}
	if deploy.Path != "/consumer/providers/cat_1/deploy" || deploy.Body["integration_setup_session_id"] != "iss_1" || deploy.Body["name"] != name {
		t.Fatalf("deploy request = %+v", deploy)
	}
	if _, ok := deploy.Body["description"]; ok {
		t.Fatalf("deploy request should omit an unset description: %+v", deploy.Body)
	}
	if reconnect.Path != "/consumer/providers/cat_1/reconnect" || reconnect.Body["magic_mcp_server_id"] != "mms_1" || reconnect.Body["integration_setup_session_id"] != "iss_2" {
		t.Fatalf("reconnect request = %+v", reconnect)
	}
}

func TestListMagicMcpServersOnlyRequestsActiveServers(t *testing.T) {
	client, requests := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]any{"items": []any{}, "pagination": map[string]any{}})
	})

	if _, err := client.ListMagicMcpServers(ListOptions{}, "", "ptpl_1"); err != nil {
		t.Fatalf("ListMagicMcpServers() error = %v", err)
	}

	request := (*requests)[0]
	if request.Path != "/magic-mcp-servers" || request.Query.Get("status") != "active" || request.Query.Get("provider_template_id") != "ptpl_1" {
		t.Fatalf("request = %s %v", request.Path, request.Query)
	}
}

func TestErrorsMapToPortalHints(t *testing.T) {
	tests := []struct {
		name    string
		status  int
		message string
		want    string
	}{
		{name: "unauthorized", status: http.StatusUnauthorized, message: "Invalid token", want: "metorial login"},
		{name: "payment required", status: http.StatusPaymentRequired, message: "Upgrade your plan", want: "not available on this organization's plan"},
		{name: "not entitled", status: http.StatusForbidden, message: "You are not entitled to access this endpoint", want: "not enabled for this organization"},
		{name: "other", status: http.StatusNotFound, message: "Catalog item not found", want: "Catalog item not found"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			client, _ := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
				writeJSON(w, tt.status, map[string]any{"status": "error", "code": "error", "message": tt.message})
			})

			_, err := client.GetProvider("cat_1")
			if err == nil {
				t.Fatalf("GetProvider() error = nil")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Fatalf("GetProvider() error = %q, want it to contain %q", err.Error(), tt.want)
			}
		})
	}
}

