package consumer

import (
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/metorial/cli/internal/browser"
	"github.com/metorial/cli/internal/consumerapi"
	"github.com/metorial/cli/internal/output"
	"github.com/metorial/cli/internal/terminal"
	"github.com/spf13/cobra"
)

const setupFallbackTimeout = 30 * time.Minute

var setupPollInterval = 2 * time.Second

type setupOptions struct {
	AuthMethodID string
	Name         string
	Description  string
}

func newSetupCommands(env commandEnv) []*cobra.Command {
	return []*cobra.Command{
		newSetupCommand(env),
		newReconnectCommand(env),
	}
}

func newSetupCommand(env commandEnv) *cobra.Command {
	options := &setupOptions{}

	command := &cobra.Command{
		Use:   "setup [catalog-item-id]",
		Short: "Configure a new integration from your portal catalog",
		Args:  cobra.RangeArgs(0, 1),
		RunE: func(command *cobra.Command, args []string) error {
			client, err := env.client()
			if err != nil {
				return err
			}

			item, err := resolveSetupItem(env, client, optionalArg(args, 0))
			if err != nil {
				return err
			}
			if err := requireConfigurable(item); err != nil {
				return err
			}

			session, err := runSetupSession(env, command, client, item, options.AuthMethodID)
			if err != nil {
				return err
			}

			server, err := client.Deploy(item.ID, consumerapi.DeployInput{
				IntegrationSetupSessionID: session.ID,
				Name:                      stringPtrIfSet(options.Name),
				Description:               stringPtrIfSet(options.Description),
			})
			if err != nil {
				return fmt.Errorf("metorial: setup completed, but the integration could not be created: %w", err)
			}

			return writeSetupResult(env, command, "Integration Ready", item, session, server)
		},
	}

	command.Flags().StringVar(&options.AuthMethodID, "auth-method", "", "Auth method ID to use (defaults to OAuth when available)")
	command.Flags().StringVar(&options.Name, "name", "", "Name for the new integration")
	command.Flags().StringVar(&options.Description, "description", "", "Description for the new integration")
	return command
}

func newReconnectCommand(env commandEnv) *cobra.Command {
	options := &setupOptions{}

	command := &cobra.Command{
		Use:   "reconnect <catalog-item-id> [integration-id]",
		Short: "Re-run setup for an existing integration and keep its endpoint URL",
		Args:  cobra.RangeArgs(1, 2),
		RunE: func(command *cobra.Command, args []string) error {
			client, err := env.client()
			if err != nil {
				return err
			}

			item, err := client.GetProvider(args[0])
			if err != nil {
				return err
			}
			if err := requireConfigurable(item); err != nil {
				return err
			}

			server, err := resolveReconnectServer(client, item, optionalArg(args, 1))
			if err != nil {
				return err
			}

			session, err := runSetupSession(env, command, client, item, options.AuthMethodID)
			if err != nil {
				return err
			}

			reconnected, err := client.Reconnect(item.ID, server.ID, session.ID)
			if err != nil {
				return fmt.Errorf("metorial: setup completed, but %s could not be reconnected: %w", integrationIdentifier(server), err)
			}

			return writeSetupResult(env, command, "Integration Reconnected", item, session, reconnected)
		},
	}

	command.Flags().StringVar(&options.AuthMethodID, "auth-method", "", "Auth method ID to use (defaults to OAuth when available)")
	return command
}

func resolveSetupItem(env commandEnv, client *consumerapi.Client, catalogItemID string) (*consumerapi.Provider, error) {
	if catalogItemID = strings.TrimSpace(catalogItemID); catalogItemID != "" {
		return client.GetProvider(catalogItemID)
	}

	if !env.app().StdoutFeatures().IsTTY {
		return nil, fmt.Errorf("metorial: a catalog item is required. Run \"metorial catalog list\" to find one, then \"metorial setup <catalog-item-id>\"")
	}

	result, err := client.ListProviders(consumerapi.ListOptions{Limit: 100}, "", "")
	if err != nil {
		return nil, err
	}

	candidates := []consumerapi.Provider{}
	labels := []string{}
	for _, item := range result.Items {
		if item.Type != consumerapi.ProviderTypeProviderTemplate || item.Availability != consumerapi.AvailabilityAvailableNow {
			continue
		}
		candidates = append(candidates, item)
		labels = append(labels, fmt.Sprintf("%s (%s)", item.Name, item.ID))
	}
	if len(candidates) == 0 {
		return nil, fmt.Errorf("metorial: no integrations are available to set up. Run \"metorial catalog list\" to see what your portal offers")
	}

	index, err := env.app().PromptSelect("Select an integration to set up", labels)
	if err != nil {
		return nil, err
	}

	return client.GetProvider(candidates[index].ID)
}

func requireConfigurable(item *consumerapi.Provider) error {
	if item.Availability == consumerapi.AvailabilityRequestAccess {
		return fmt.Errorf("metorial: you don't have access to %s yet. Run \"metorial request-access %s\" to ask for it", item.Name, item.ID)
	}
	if item.Type != consumerapi.ProviderTypeProviderTemplate {
		return fmt.Errorf("metorial: %s is a shared integration and is ready to use. Run \"%s\"", item.Name, catalogNextStep(*item))
	}
	return nil
}

func resolveReconnectServer(client *consumerapi.Client, item *consumerapi.Provider, integrationID string) (*consumerapi.MagicMcpServer, error) {
	if integrationID = strings.TrimSpace(integrationID); integrationID != "" {
		return client.GetMagicMcpServer(integrationID)
	}

	servers, err := client.ListMagicMcpServers(consumerapi.ListOptions{Limit: 50}, "", item.ProviderTemplate.ID)
	if err != nil {
		return nil, err
	}

	switch len(servers.Items) {
	case 0:
		return nil, fmt.Errorf("metorial: you have no integrations for %s yet. Run \"metorial setup %s\" to create one", item.Name, item.ID)
	case 1:
		return &servers.Items[0], nil
	default:
		ids := make([]string, 0, len(servers.Items))
		for index := range servers.Items {
			ids = append(ids, integrationIdentifier(&servers.Items[index]))
		}
		return nil, fmt.Errorf("metorial: you have several integrations for %s (%s). Pass the one to reconnect: \"metorial reconnect %s <integration-id>\"", item.Name, strings.Join(ids, ", "), item.ID)
	}
}

func runSetupSession(env commandEnv, command *cobra.Command, client *consumerapi.Client, item *consumerapi.Provider, authMethodID string) (*consumerapi.SetupSession, error) {
	if strings.TrimSpace(authMethodID) == "" {
		authMethodID = preferredAuthMethodID(item)
	}

	session, err := client.StartSetup(item.ID, authMethodID)
	if err != nil {
		return nil, err
	}
	if session.Status == consumerapi.SetupStatusSuccessful {
		return session, nil
	}

	structured, err := env.structured()
	if err != nil {
		return nil, err
	}

	writer := command.ErrOrStderr()
	features := env.app().StderrFeatures()
	if structured {
		writer = command.OutOrStdout()
		features = env.app().StdoutFeatures()
	}

	if strings.TrimSpace(session.URL) != "" {
		if err := renderSetupPrompt(writer, features, item, session); err != nil {
			return nil, err
		}
	}

	return waitForSetupSession(writer, features, client, item.ID, session)
}

func preferredAuthMethodID(item *consumerapi.Provider) string {
	for _, method := range item.AuthMethods {
		if method.Type == "oauth" {
			return method.ID
		}
	}
	return ""
}

func renderSetupPrompt(writer io.Writer, features terminal.Features, item *consumerapi.Provider, session *consumerapi.SetupSession) error {
	colors := terminal.NewColorizer(features)
	browserOpenSupported := browser.Supported()

	summary := fmt.Sprintf("%s\n%s", colors.Notice("Open this URL to finish setting up "+item.Name), colors.Bold(session.URL))
	if browserOpenSupported {
		summary = fmt.Sprintf("%s\n%s", colors.Success("Opened setup for "+item.Name+" in your browser"), colors.Bold(session.URL))
	}

	lines := []string{
		summary,
		fmt.Sprintf("%s %s", colors.Muted("Setup session:"), colors.Bold(session.ID)),
	}
	if !session.ExpiresAt.IsZero() {
		lines = append(lines, fmt.Sprintf("%s %s", colors.Muted("Expires:"), session.ExpiresAt.Local().Format("2006-01-02 15:04:05")))
	}

	if err := output.RenderBox(writer, lines, output.BoxOptions{
		MaxWidth: features.Width,
		Unicode:  features.HasUnicode,
	}); err != nil {
		return err
	}
	_, _ = fmt.Fprintln(writer)

	if browserOpenSupported {
		_ = browser.Open(session.URL)
	}
	return nil
}

func waitForSetupSession(writer io.Writer, features terminal.Features, client *consumerapi.Client, catalogItemID string, session *consumerapi.SetupSession) (*consumerapi.SetupSession, error) {
	deadline := session.ExpiresAt
	if deadline.IsZero() {
		deadline = time.Now().Add(setupFallbackTimeout)
	}

	spinner := terminal.NewSpinner(writer, features, "Waiting for setup to complete")
	spinner.Start()
	defer spinner.Stop()

	for {
		current, err := client.GetSetup(catalogItemID, session.ID)
		if err != nil {
			return nil, err
		}

		switch current.Status {
		case consumerapi.SetupStatusSuccessful:
			return current, nil
		case consumerapi.SetupStatusExpired:
			return nil, fmt.Errorf("metorial: setup session %s expired before it was completed", current.ID)
		case consumerapi.SetupStatusArchived, consumerapi.SetupStatusDeleted:
			return nil, fmt.Errorf("metorial: setup session %s was cancelled before it was completed", current.ID)
		}

		if time.Now().After(deadline) {
			return nil, fmt.Errorf("metorial: setup session %s expired before it was completed", current.ID)
		}

		time.Sleep(setupPollInterval)
	}
}

func writeSetupResult(env commandEnv, command *cobra.Command, title string, item *consumerapi.Provider, session *consumerapi.SetupSession, server *consumerapi.MagicMcpServer) error {
	tips := append([]string{fmt.Sprintf("metorial get %s", integrationIdentifier(server))}, integrationTips(server, true)...)

	return env.write(command, map[string]any{
		"item":          item,
		"setup_session": session,
		"integration":   server,
		"tips":          tips,
	}, func(writer io.Writer, features terminal.Features) error {
		colors := terminal.NewColorizer(features)
		_, _ = fmt.Fprintln(writer, colors.Success(title))
		_, _ = fmt.Fprintln(writer)
		renderTitle(writer, features, integrationTitle(server), server.ID)

		if err := output.RenderDataList(writer, []output.DataListItem{
			{Label: "Status", Value: server.Status},
			{Label: "Catalog Item", Value: fmt.Sprintf("%s (%s)", item.Name, item.ID)},
		}); err != nil {
			return err
		}
		if err := renderServerEndpoints(writer, features, server); err != nil {
			return err
		}
		return renderTips(writer, features, tips)
	})
}

package auth

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

type Client struct {
	baseURL    *url.URL
	httpClient *http.Client
}

type StartResponse struct {
	ID               string `json:"id"`
	Token            string `json:"token"`
	ExpiresIn        int    `json:"expires_in"`
	Interval         int    `json:"interval"`
	UserCode         string `json:"user_code"`
	AuthorizationURL string `json:"authorization_url"`
}

type TokenResponse struct {
	AccessToken     string               `json:"access_token"`
	TokenType       string               `json:"token_type"`
	RefreshToken    string               `json:"refresh_token"`
	ExpiresIn       int                  `json:"expires_in"`
	ClientID        string               `json:"client_id"`
	User            UserInfo             `json:"user"`
	Organization    OrgInfo              `json:"organization"`
	Scope           ScopeValues          `json:"scope"`
	SubjectType     string               `json:"subject_type"`
	ConsumerProfile *ConsumerProfileInfo `json:"consumer_profile"`
	Portal          *PortalInfo          `json:"portal"`
	Instance        *InstanceInfo        `json:"instance"`
}

type ConsumerProfileInfo struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

type PortalInfo struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type InstanceInfo struct {
	ID string `json:"id"`
}

type UserInfo struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

type OrgInfo struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type ScopeValues []string

type Error struct {
	StatusCode   int
	ErrorCode    string `json:"error"`
	ErrorMessage string `json:"error_message"`
}

func NewClient(baseURL *url.URL) *Client {
	return &Client{
		baseURL:    baseURL,
		httpClient: &http.Client{Timeout: 30 * time.Second},
	}
}

func (c *Client) StartCLIAuth(subjectType string) (*StartResponse, error) {
	response := &StartResponse{}
	values := url.Values{}
	if subjectType = strings.TrimSpace(subjectType); subjectType != "" {
		values.Set("subject_type", subjectType)
	}
	if err := c.postForm("/cli/auth/start", values, response); err != nil {
		return nil, err
	}
	return response, nil
}

func (c *Client) CompleteCLIAuth(token string) (*TokenResponse, error) {
	response := &TokenResponse{}
	values := url.Values{}
	values.Set("token", strings.TrimSpace(token))
	if err := c.postForm("/cli/auth/complete", values, response); err != nil {
		return nil, err
	}
	return response, nil
}

func (c *Client) RefreshToken(clientID, refreshToken string) (*TokenResponse, error) {
	response := &TokenResponse{}
	values := url.Values{}
	values.Set("grant_type", "refresh_token")
	values.Set("client_id", strings.TrimSpace(clientID))
	values.Set("refresh_token", strings.TrimSpace(refreshToken))
	if err := c.postForm("/oauth/token", values, response); err != nil {
		return nil, err
	}
	return response, nil
}

func (c *Client) postForm(path string, values url.Values, output any) error {
	requestURL := c.baseURL.ResolveReference(&url.URL{Path: path})
	request, err := http.NewRequest(http.MethodPost, requestURL.String(), bytes.NewBufferString(values.Encode()))
	if err != nil {
		return fmt.Errorf("metorial: failed to create auth request: %w", err)
	}

	request.Header.Set("Accept", "application/json")
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")

	response, err := c.httpClient.Do(request)
	if err != nil {
		return fmt.Errorf("metorial: authentication request failed: %w", err)
	}
	defer response.Body.Close()

	body, err := io.ReadAll(response.Body)
	if err != nil {
		return fmt.Errorf("metorial: failed to read authentication response: %w", err)
	}

	if response.StatusCode < 200 || response.StatusCode >= 300 {
		apiError := &Error{StatusCode: response.StatusCode}
		_ = json.Unmarshal(body, apiError)
		if strings.TrimSpace(apiError.ErrorMessage) == "" {
			apiError.ErrorMessage = http.StatusText(response.StatusCode)
		}
		return apiError
	}

	if output == nil || len(bytes.TrimSpace(body)) == 0 {
		return nil
	}

	if err := json.Unmarshal(body, output); err != nil {
		return fmt.Errorf("metorial: failed to parse authentication response: %w", err)
	}

	return nil
}

func (s *ScopeValues) UnmarshalJSON(data []byte) error {
	trimmed := bytes.TrimSpace(data)
	if len(trimmed) == 0 || bytes.Equal(trimmed, []byte("null")) {
		*s = nil
		return nil
	}

	var text string
	if err := json.Unmarshal(trimmed, &text); err == nil {
		parts := strings.Fields(text)
		*s = append((*s)[:0], parts...)
		return nil
	}

	var values []string
	if err := json.Unmarshal(trimmed, &values); err != nil {
		return err
	}

	*s = values
	return nil
}

func (e *Error) Error() string {
	if strings.TrimSpace(e.ErrorMessage) != "" {
		return e.ErrorMessage
	}
	if strings.TrimSpace(e.ErrorCode) != "" {
		return e.ErrorCode
	}
	return "authentication failed"
}

package consumer

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"

	"github.com/metorial/cli/internal/consumerapi"
	"github.com/metorial/cli/internal/output"
	"github.com/metorial/cli/internal/terminal"
	"github.com/pelletier/go-toml/v2"
	"github.com/spf13/cobra"
	"github.com/tailscale/hujson"
	"gopkg.in/yaml.v3"
)

type installTransport string

const (
	installTransportSSE            installTransport = "sse"
	installTransportStreamableHTTP installTransport = "streamable_http"
)

type installPlanMethod string

const (
	installPlanMethodCommand installPlanMethod = "command"
	installPlanMethodFile    installPlanMethod = "file"
)

type remoteServerDefinition struct {
	Name      string
	URL       string
	Transport installTransport
}

type clientCapabilities struct {
	Transports []installTransport
}

type commandInstallPlan struct {
	Method    installPlanMethod `json:"method"`
	Command   string            `json:"command"`
	Args      []string          `json:"args"`
	Transport installTransport  `json:"transport"`
}

type fileInstallPlan struct {
	Method    installPlanMethod `json:"method"`
	Format    string            `json:"format"`
	Path      string            `json:"path"`
	Content   map[string]any    `json:"content"`
	Transport installTransport  `json:"transport"`
}

type clientInstallPlan interface {
	method() installPlanMethod
	transport() installTransport
}

func (p commandInstallPlan) method() installPlanMethod   { return p.Method }
func (p commandInstallPlan) transport() installTransport { return p.Transport }
func (p fileInstallPlan) method() installPlanMethod      { return p.Method }
func (p fileInstallPlan) transport() installTransport    { return p.Transport }

type clientDetection struct {
	Installed bool   `json:"installed"`
	Usable    bool   `json:"usable"`
	Location  string `json:"location,omitempty"`
}

type clientAdapter interface {
	id() string
	label() string
	capabilities() clientCapabilities
	detect() clientDetection
	buildInstallPlan(server remoteServerDefinition) (clientInstallPlan, error)
}

type remoteCommandTemplate func(remoteCommandInput) []string

type remoteCommandInput struct {
	Name      string
	URL       string
	Transport installTransport
}

type commandClientAdapter struct {
	clientID           string
	clientLabel        string
	command            string
	template           remoteCommandTemplate
	clientCapabilities clientCapabilities
}

func (a commandClientAdapter) id() string                       { return a.clientID }
func (a commandClientAdapter) label() string                    { return a.clientLabel }
func (a commandClientAdapter) capabilities() clientCapabilities { return a.clientCapabilities }
func (a commandClientAdapter) detect() clientDetection {
	path, err := exec.LookPath(a.command)
	if err != nil {
		return clientDetection{}
	}
	return clientDetection{Installed: true, Usable: true, Location: path}
}
func (a commandClientAdapter) buildInstallPlan(server remoteServerDefinition) (clientInstallPlan, error) {
	return commandInstallPlan{
		Method:    installPlanMethodCommand,
		Command:   a.command,
		Args:      a.template(remoteCommandInput{Name: server.Name, URL: server.URL, Transport: server.Transport}),
		Transport: server.Transport,
	}, nil
}

type codexClientAdapter struct {
	commandAdapter commandClientAdapter
	fileAdapter    fileClientAdapter
}

func (a codexClientAdapter) id() string                       { return a.commandAdapter.id() }
func (a codexClientAdapter) label() string                    { return a.commandAdapter.label() }
func (a codexClientAdapter) capabilities() clientCapabilities { return a.commandAdapter.capabilities() }
func (a codexClientAdapter) detect() clientDetection {
	commandDetection := a.commandAdapter.detect()
	if commandDetection.Usable {
		return commandDetection
	}

	filePath := expandPath(a.fileAdapter.path)
	parentDir := filepath.Dir(filePath)
	if dirExists(parentDir) || dirExists(filepath.Dir(parentDir)) || strings.TrimSpace(filePath) != "" {
		return clientDetection{
			Installed: fileExists(filePath),
			Usable:    true,
			Location:  filePath,
		}
	}

	return clientDetection{Location: filePath}
}
func (a codexClientAdapter) buildInstallPlan(server remoteServerDefinition) (clientInstallPlan, error) {
	if a.commandAdapter.detect().Usable {
		return a.commandAdapter.buildInstallPlan(server)
	}
	return a.fileAdapter.buildInstallPlan(server)
}

type fileFieldNames struct {
	Type    string
	URL     string
	Headers string
}

type fileClientAdapter struct {
	clientID           string
	clientLabel        string
	format             string
	path               string
	topLevelKey        string
	fieldNames         fileFieldNames
	typeValue          map[installTransport]string
	includeTypeField   bool
	clientCapabilities clientCapabilities
}

func (a fileClientAdapter) id() string                       { return a.clientID }
func (a fileClientAdapter) label() string                    { return a.clientLabel }
func (a fileClientAdapter) capabilities() clientCapabilities { return a.clientCapabilities }
func (a fileClientAdapter) detect() clientDetection {
	path := expandPath(a.path)
	if fileExists(path) || dirExists(filepath.Dir(path)) {
		return clientDetection{Installed: true, Usable: true, Location: path}
	}
	return clientDetection{Installed: false, Usable: false, Location: path}
}
func (a fileClientAdapter) buildInstallPlan(server remoteServerDefinition) (clientInstallPlan, error) {
	containerKey := firstNonEmpty(a.topLevelKey, "mcpServers")
	typeField := firstNonEmpty(a.fieldNames.Type, "type")
	urlField := firstNonEmpty(a.fieldNames.URL, "url")
	headersField := firstNonEmpty(a.fieldNames.Headers, "headers")
	includeTypeField := true
	if !a.includeTypeField {
		includeTypeField = false
	}

	entry := map[string]any{
		urlField: server.URL,
	}
	if includeTypeField {
		typeValue := a.typeValue[server.Transport]
		if strings.TrimSpace(typeValue) == "" {
			typeValue = transportTypeValue(server.Transport)
		}
		entry[typeField] = typeValue
	}

	return fileInstallPlan{
		Method:    installPlanMethodFile,
		Format:    a.format,
		Path:      expandPath(a.path),
		Content:   map[string]any{containerKey: map[string]any{server.Name: entry}, "_headers_field": headersField},
		Transport: server.Transport,
	}, nil
}

type integrationClientRow struct {
	ID        string `json:"id"`
	Label     string `json:"label"`
	Method    string `json:"method"`
	Transport string `json:"transport"`
	Installed bool   `json:"installed"`
	Usable    bool   `json:"usable"`
	Location  string `json:"location,omitempty"`
}

type integrationInstallResult struct {
	Client      string              `json:"client,omitempty"`
	Method      string              `json:"method,omitempty"`
	Transport   string              `json:"transport"`
	Integration string              `json:"integration"`
	EndpointURL string              `json:"endpoint_url"`
	TokenID     string              `json:"token_id"`
	Token       string              `json:"token,omitempty"`
	Command     *commandInstallPlan `json:"command,omitempty"`
	File        *fileInstallPlan    `json:"file,omitempty"`
}

func newInstallCommands(env commandEnv) []*cobra.Command {
	clientCommand := &cobra.Command{
		Use:   "client",
		Short: "Inspect supported local MCP clients",
	}
	clientCommand.AddCommand(&cobra.Command{
		Use:   "list",
		Short: "List supported MCP clients and installation availability",
		Args:  cobra.NoArgs,
		RunE: func(command *cobra.Command, args []string) error {
			rows := integrationClientRows()
			tips := []string{
				"metorial install codex <integration-id>",
				"metorial install custom <integration-id>",
			}

			return env.write(command, map[string]any{
				"items": rows,
				"tips":  tips,
			}, func(writer io.Writer, features terminal.Features) error {
				return renderIntegrationClientList(writer, features, rows, tips)
			})
		},
	})

	installCommand := &cobra.Command{
		Use:   "install <client-identifier> <integration-id>",
		Short: "Install an integration into a local MCP client",
		Args:  cobra.ExactArgs(2),
		RunE: func(command *cobra.Command, args []string) error {
			adapter, err := integrationClientByID(args[0])
			if err != nil {
				return err
			}
			detection := adapter.detect()
			if !detection.Usable {
				return fmt.Errorf("metorial: %s is not installed or cannot be used on this system. Run `metorial client list` for supported clients", adapter.label())
			}

			server, token, endpointURL, err := createInstallEndpoint(env, args[1])
			if err != nil {
				return err
			}

			plan, err := adapter.buildInstallPlan(remoteServerDefinition{
				Name:      integrationIdentifier(server),
				URL:       endpointURL,
				Transport: selectInstallTransport(adapter.capabilities()),
			})
			if err != nil {
				return err
			}
			if err := executeIntegrationInstallPlan(plan); err != nil {
				return err
			}

			result := integrationInstallResult{
				Client:      adapter.label(),
				Method:      string(plan.method()),
				Transport:   string(plan.transport()),
				Integration: integrationIdentifier(server),
				EndpointURL: endpointURL,
				TokenID:     token.ID,
			}
			switch typed := plan.(type) {
			case commandInstallPlan:
				result.Command = &typed
			case fileInstallPlan:
				result.File = &typed
			}

			return env.write(command, result, func(writer io.Writer, features terminal.Features) error {
				return renderIntegrationInstallResult(writer, features, result)
			})
		},
	}
	installCommand.AddCommand(&cobra.Command{
		Use:   "custom <integration-id>",
		Short: "Create an installation token and show the endpoint details",
		Args:  cobra.ExactArgs(1),
		RunE: func(command *cobra.Command, args []string) error {
			server, token, endpointURL, err := createInstallEndpoint(env, args[0])
			if err != nil {
				return err
			}

			result := integrationInstallResult{
				Client:      "custom",
				Method:      "custom",
				Transport:   string(installTransportStreamableHTTP),
				Integration: integrationIdentifier(server),
				EndpointURL: endpointURL,
				TokenID:     token.ID,
				Token:       [REDACTED],
			}

			return env.write(command, result, func(writer io.Writer, features terminal.Features) error {
				return renderCustomInstallResult(writer, features, result)
			})
		},
	})

	return []*cobra.Command{clientCommand, installCommand}
}

func createInstallEndpoint(env commandEnv, integrationID string) (*consumerapi.MagicMcpServer, *consumerapi.MagicMcpToken, string, error) {
	client, err := env.client()
	if err != nil {
		return nil, nil, "", err
	}

	server, err := client.GetMagicMcpServer(integrationID)
	if err != nil {
		return nil, nil, "", err
	}

	token, err := createMagicMcpInstallToken(client, server.ID)
	if err != nil {
		return nil, nil, "", err
	}

	endpointURL, err := buildMagicMcpInstallURL(server, token.Secret)
	if err != nil {
		return nil, nil, "", err
	}

	return server, token, endpointURL, nil
}

