package agent

import "os"

var envVarAgents = map[string]string{
	"ANTIGRAVITY_CLI_ALIAS":          "antigravity",
	"CLAUDECODE":                     "claude_code",
	"CLINE_ACTIVE":                   "cline",
	"CODEX_SANDBOX":                  "codex_cli",
	"CODEX_THREAD_ID":                "codex_cli",
	"CODEX_SANDBOX_NETWORK_DISABLED": "codex_cli",
	"CODEX_CI":                       "codex_cli",
	"CURSOR_AGENT":                   "cursor",
	"GEMINI_CLI":                     "gemini_cli",
	"OPENCODE":                       "open_code",
}

func IsAiAgent() (bool, string) {
	for envVar, agentName := range envVarAgents {
		if os.Getenv(envVar) != "" {
			return true, agentName
		}
	}

	return false, ""
}

package browser

import (
	"fmt"
	"os/exec"
	"runtime"
)

func opener() (string, []string, bool) {
	switch runtime.GOOS {
	case "darwin":
		if _, err := exec.LookPath("open"); err == nil {
			return "open", nil, true
		}
	case "linux":
		if _, err := exec.LookPath("xdg-open"); err == nil {
			return "xdg-open", nil, true
		}
	case "windows":
		if _, err := exec.LookPath("rundll32"); err == nil {
			return "rundll32", []string{"url.dll,FileProtocolHandler"}, true
		}
	}

	return "", nil, false
}

func Supported() bool {
	_, _, ok := opener()
	return ok
}

func Open(target string) error {
	command, args, ok := opener()
	if !ok {
		return fmt.Errorf("opening a browser is not supported on this system")
	}

	args = append(args, target)

	if err := exec.Command(command, args...).Start(); err != nil {
		return fmt.Errorf("failed to open browser: %w", err)
	}

	return nil
}
